 INSERT INTO ops_api_atomic_transport_bb0bd0ce.payload_parts(ordinal,payload) VALUES (6,$ops_compact_part_6$r-ARRAY[''kind'',''baselineSourceMessageId'',''baselineAssessmentId'',''baselineFactsHash'',''supplyPeriodId'',''switchRequestId'',''switchCreatedAt'',''outboundSourceMessageId'',''outboundCreatedAt'',''validFrom'',''validTo'']<>''{}''::jsonb\n OR NOT cover ?& ARRAY[''kind'',''baselineSourceMessageId'',''baselineAssessmentId'',''baselineFactsHash'',''supplyPeriodId'',''switchRequestId'',''switchCreatedAt'',''outboundSourceMessageId'',''outboundCreatedAt'',''validFrom'',''validTo'']\n OR wire->''object'' IS DISTINCT FROM p_business->''object'' OR wire->>''messageCode'' IS DISTINCT FROM src.message_code\n OR wire->>''legalSender'' IS DISTINCT FROM p_party#>>''{parties,legalSender}'' OR wire->>''legalReceiver'' IS DISTINCT FROM p_party#>>''{parties,legalReceiver}''\n OR wire->>''transportSender'' IS DISTINCT FROM p_party#>>''{parties,transportSender}'' OR wire->>''transportReceiver'' IS DISTINCT FROM p_party#>>''{parties,transportReceiver}''\n THEN RETURN false; END IF;\n SELECT * INTO review_snap FROM gridex_received_sources.object_selection_snapshots\n WHERE id=(p_business#>>''{reviewSnapshot,snapshotId}'')::uuid AND company_id=src.company_id AND environment=src.environment\n AND readset_hash=p_business#>>''{reviewSnapshot,readsetHash}'' AND cutoff_at=(p_business#>>''{reviewSnapshot,cutoffAt}'')::timestamptz;\n IF NOT FOUND OR (review_snap.readset_text::jsonb->>''complete'') IS DISTINCT FROM ''true''\n OR review_snap.cutoff_at>(p_business->>''assessedAt'')::timestamptz\n OR NOT EXISTS(SELECT FROM jsonb_array_elements(review_snap.readset_text::jsonb->''sources'') item\n   WHERE item->>''sourceMessageId''=src.source_message_id::text AND item->>''payloadHash''=src.payload_hash) THEN RETURN false; END IF;\n SELECT opened_at INTO epoch FROM gridex_received_sources.epoch WHERE singleton;\n valid_start:=(cover->>''validFrom'')::timestamptz; valid_end:=(cover->>''validTo'')::timestamptz;\n minute:=wire#>>''{effectiveTo,marketMinute}'';\n IF minute IS NULL OR minute !~ ''^[0-9]{12}$'' OR substring(minute,1,4)::int<1 OR substring(minute,9,2)::int>23 OR substring(minute,11,2)::int>59 THEN RETURN false; END IF;\n market_time:=make_timestamp(substring(minute,1,4)::int,substring(minute,5,2)::int,substring(minute,7,2)::int,substring(minute,9,2)::int,substring(minute,11,2)::int,0);\n change_at:=market_time AT TIME ZONE ''Etc/GMT-1'';\n IF (wire#>>''{effectiveTo,utc}'')::timestamptz IS DISTINCT FROM change_at OR valid_start IS NULL OR NOT isfinite(valid_start)\n OR valid_start<epoch OR (valid_end IS NOT NULL AND (NOT isfinite(valid_end) OR valid_end<=valid_start))\n OR change_at<=valid_start OR (valid_end IS NOT NULL AND change_at<>valid_end)\n OR p_business->>''legacyEndDateProjection'' IS DISTINCT FROM market_time::date::text THEN RETURN false; END IF;\n SELECT * INTO baseline FROM gridex_received_sources.sources WHERE source_message_id=(cover->>''baselineSourceMessageId'')::uuid\n AND company_id=src.company_id AND environment=src.environment AND message_code=''Z04'';\n IF NOT FOUND OR baseline.source_message_id=src.source_message_id OR reference IS DISTINCT FROM jsonb_build_object(\n  ''sourceMessageId'',baseline.source_message_id,''assessmentId'',p_business->>''baselineCurrentAssessmentId'',\n  ''factsHash'',reference->>''factsHash'',''payloadHash'',baseline.payload_hash) THEN RETURN false; END IF;\n SELECT a.* INTO root FROM gridex_received_sources.object_assessments a JOIN gridex_received_sources.object_availability_witnesses w ON w.assessment_id=a.id\n WHERE a.id=(cover->>''baselineAssessmentId'')::uuid AND a.source_message_id=baseline.source_message_id AND a.company_id=src.company_id\n AND a.environment=src.environment AND a.facts_hash=cover->>''baselineFactsHash'' AND w.facts_hash=a.facts_hash AND w.observed_at<=review_snap.cutoff_at;\n IF NOT FOUND THEN RETURN false; END IF;\n SELECT value INTO root_entry FROM jsonb_array_elements(root.facts_text::jsonb->''objects'')\n WHERE value#>>''{object,objectId}''=p_business#>>''{object,objectId}'' AND value#>>''{object,identityAgency}''=''9'';\n IF root_entry->>''disposition'' IS DISTINCT FROM ''accepted'' OR root_entry#>>''{business,owner}'' IS DISTINCT FROM ''inbound-z04-switch-confirmation-v1''\n OR root.source_payload_hash IS DISTINCT FROM baseline.payload_hash\n OR root_entry#>>''{business,sourceMessageId}'' IS DISTINCT FROM baseline.source_message_id::text\n OR root_entry#>>''{business,sourcePayloadHash}'' IS DISTINCT FROM baseline.payload_hash\n OR root_entry#>>''{business,companyId}'' IS DISTINCT FROM src.company_id::text\n OR root_entry#>>''{business,environment}'' IS DISTINCT FROM src.environment\n OR root_entry#>>''{party,parties,legalSender}'' IS DISTINCT FROM wire->>''legalSender''\n OR root_entry#>>''{party,parties,legalReceiver}'' IS DISTINCT FROM wire->>''legalReceiver''\n OR root_entry#>>''{business,switchRequestId}'' IS DISTINCT FROM p_business->>''switchRequestId''\n OR root_entry#>>''{business,supplyPeriodId}'' IS DISTINCT FROM p_business->>''supplyPeriodId''\n OR root_entry#>>''{business,customerId}'' IS DISTINCT FROM p_business->>''customerId''\n OR root_entry#>>''{business,meteringPointId}'' IS DISTINCT FROM p_business->>''meteringPointId''\n OR root_entry#>>''{business,siteId}'' IS DISTINCT FROM p_business->>''siteId''\n OR (root_entry#>>''{business,effectiveFrom,utc}'')::timestamptz IS DISTINCT FROM valid_start THEN RETURN false; END IF;\n SELECT a.* INTO current_root FROM gridex_received_sources.object_assessments a JOIN gridex_received_sources.object_availability_witnesses w ON w.assessment_id=a.id\n WHERE a.id=(p_business->>''baselineCurrentAssessmentId'')::uuid AND a.source_message_id=baseline.source_message_id\n AND a.company_id=src.company_id AND a.environment=src.environment AND w.facts_hash=a.facts_hash AND w.observed_at<=review_snap.cutoff_at\n AND NOT EXISTS(SELECT FROM gridex_received_sources.object_assessments next WHERE next.previous_assessment_id=a.id);\n IF NOT FOUND THEN RETURN false; END IF;\n SELECT value INTO current_entry FROM jsonb_array_elements(current_root.facts_text::jsonb->''objects'')\n WHERE value#>>''{object,objectId}''=p_business#>>''{object,objectId}'' AND value#>>''{object,identityAgency}''=''9'';\n IF current_entry->>''disposition'' IS DISTINCT FROM ''accepted''\n OR current_entry#>>''{business,owner}'' IS DISTINCT FROM ''reviewed-received-structure-v1''\n OR current_entry#>>''{business,wire,messageCode}'' IS DISTINCT FROM ''Z04''\n OR current_entry#>''{business,wire,functionCode}'' NOT IN (''\"9\"''::jsonb,''null''::jsonb)\n OR current_entry#>''{business,replaces}'' IS DISTINCT FROM ''null''::jsonb\n OR current_entry#>''{business,coverageWindow}'' IS DISTINCT FROM cover\n OR current_root.facts_hash IS DISTINCT FROM reference->>''factsHash''\n OR current_root.source_payload_hash IS DISTINCT FROM baseline.payload_hash\n OR current_entry#>>''{business,sourceMessageId}'' IS DISTINCT FROM baseline.source_message_id::text\n OR current_entry#>>''{business,sourcePayloadHash}'' IS DISTINCT FROM baseline.payload_hash\n OR current_entry#>>''{business,companyId}'' IS DISTINCT FROM src.company_id::text\n OR current_entry#>>''{business,environment}'' IS DISTINCT FROM src.environment\n OR current_entry#>>''{business,customerId}'' IS DISTINCT FROM p_business->>''customerId''\n OR current_entry#>>''{business,meteringPointId}'' IS DISTINCT FROM p_business->>''meteringPointId''\n OR current_entry#>>''{business,siteId}'' IS DISTINCT FROM p_business->>''siteId''\n OR current_entry#>>''{business,switchRequestId}'' IS DISTINCT FROM p_business->>''switchRequestId''\n OR current_entry#>>''{business,supplyPeriodId}'' IS DISTINCT FROM p_business->>''supplyPeriodId''\n OR current_entry#>>''{business,wire,legalSender}'' IS DISTINCT FROM wire->>''legalSender''\n OR current_entry#>>''{business,wire,legalReceiver}'' IS DISTINCT FROM wire->>''legalReceiver''\n OR (current_entry#>>''{business,wire,effectiveFrom,utc}'')::timestamptz IS DISTINCT FROM valid_start\n THEN RETURN false; END IF;\n -- The retained snapshot must actually contain the current baseline assessment,\n -- rather than merely sharing a plausible time and tenant with it.\n IF NOT EXISTS(SELECT FROM jsonb_array_elements(review_snap.readset_text::jsonb->''sources'') source,\n  LATERAL jsonb_array_elements(source->''assessments'') assessment\n  WHERE source->>''sourceMessageId''=baseline.source_message_id::text AND source->>''payloadHash''=baseline.payload_hash\n  AND assessment->>''id''=root.id::text AND assessment->>''factsHash''=root.facts_hash\n  AND (assessment->>''availableAt'')::timestamptz<=review_snap.cutoff_at) THEN RETURN false; END IF;\n IF NOT EXISTS(SELECT FROM jsonb_array_elements(review_snap.readset_text::jsonb->''sources'') source,\n  LATERAL jsonb_array_elements(source->''assessments'') assessment\n  WHERE source->>''sourceMessageId''=baseline.source_message_id::text AND assessment->>''id''=current_root.id::text\n  AND assessment->>''factsHash''=current_root.facts_hash AND (assessment->>''availableAt'')::timestamptz<=review_snap.cutoff_at) THEN RETURN false; END IF;\n -- Selection may not choose a convenient reviewed root among ambiguous\n -- latest witnessed baselines for this same immutable supply and object.\n IF (SELECT count(*) FROM gridex_received_sources.object_assessments a\n  JOIN gridex_received_sources.object_availability_witnesses w ON w.assessment_id=a.id AND w.facts_hash=a.facts_hash\n  JOIN gridex_received_sources.sources source ON source.source_message_id=a.source_message_id\n  CROSS JOIN LATERAL jsonb_array_elements(a.facts_text::jsonb->''objects'') item\n  WHERE a.company_id=src.company_id AND a.environment=src.environment AND source.message_code=''Z04''\n  AND w.observed_at<=review_snap.cutoff_at\n  AND NOT EXISTS(SELECT FROM gridex_received_sources.object_assessments child WHERE child.previous_assessment_id=a.id)\n  AND item->>''disposition''=''accepted'' AND item#>>''{business,owner}''=''reviewed-received-structure-v1''\n  AND item#>>''{business,supplyPeriodId}''=p_business->>''supplyPeriodId''\n  AND item#>>''{object,objectId}''=p_business#>>''{object,objectId}'' AND item#>>''{object,identityAgency}''=''9''\n  AND item#>>''{business,wire,legalSender}''=wire->>''legalSender''\n  AND item#>>''{business,wire,legalReceiver}''=wire->>''legalReceiver'')<>1 THEN RETURN false; END IF;\n IF (SELECT count(*) FROM public.customer_supply_periods sp WHERE sp.company_id=src.company_id\n  AND sp.source_message_id=src.source_message_id AND sp.status=''ended''\n  AND sp.customer_id=(p_business->>''customerId'')::uuid AND sp.metering_point_id=(p_business->>''meteringPointId'')::uuid)<>1 THEN RETURN false; END IF;\n SELECT EXISTS(SELECT FROM public.supplier_switch_requests sw\n JOIN public.customer_supply_periods sp ON sp.id=(p_business->>''supplyPeriodId'')::uuid\n JOIN public.ediel_messages outbound ON outbound.id=sw.outbound_z03_message_id\n JOIN public.metering_points mp ON mp.id=sw.metering_point_id JOIN public.customer_sites cs ON cs.id=sw.site_id\n WHERE sw.id=(p_business->>''switchRequestId'')::uuid AND sw.company_id=src.company_id AND sp.company_id=src.company_id\n AND sw.inbound_z04_message_id=baseline.source_message_id AND sp.source_message_id=src.source_message_id\n AND sw.status=''accepted'' AND sp.status=''ended''\n AND sw.rff_li_reference=current_entry#>>''{business,wire,caseReference}''\n AND sw.metering_point_id=(p_business->>''meteringPointId'')::uuid AND sp.metering_point_id=sw.metering_point_id\n AND sw.customer_id=(p_business->>''customerId'')::uuid AND sp.customer_id=sw.customer_id AND sw.site_id=(p_business->>''siteId'')::uuid\n AND (sp.source_switch_request_id IS NULL OR sp.source_switch_request_id=sw.id)\n AND mp.company_id=src.company_id AND cs.company_id=src.company_id AND mp.site_id=cs.id AND mp.customer_id=sw.customer_id AND cs.customer_id=sw.customer_id\n AND (sp.start_date::timestamp AT TIME ZONE ''Etc/GMT-1'')=valid_start AND sw.confirmed_start_date=sp.start_date\n AND sp.end_date=market_time::date\n AND sw.created_at=(cover->>''switchCreatedAt'')::timestamptz AND sw.created_at>=epoch AND sw.created_at<=valid_start\n AND outbound.id=(cover->>''outboundSourceMessageId'')::uuid AND outbound.company_id=src.company_id AND outbound.environment=src.environment\n AND outbound.direction=''outbound'' AND outbound.message_standard=''edifact'' AND outbound.message_family=''PRODAT'' AND outbound.message_code=''Z03''\n AND outbound.created_at=(cover->>''outboundCreatedAt'')::timestamptz AND outbound.created_at>=sw.created_at AND outbound.created_at<=review_snap.cutoff_at\n AND outbound.message_sent_at>=outbound.created_at AND outbound.message_sent_at<=baseline.source_received_at\n AND outbound.customer_id=sw.customer_id AND outbound.metering_point_id=sw.metering_point_id AND outbound.site_id=sw.site_id) INTO owner_ok;\n IF owner_ok IS DISTINCT FROM true THEN RETURN false; END IF;\n RETURN true;\nEXCEPTION WHEN invalid_text_representation OR invalid_datetime_format OR datetime_field_overflow OR numeric_value_out_of_range OR invalid_parameter_value THEN RETURN false;\nEND ","patched":"\nDECLARE src gridex_received_sources.sources%rowtype; baseline gridex_received_sources.sources%rowtype;\n root gridex_received_sources.object_assessments%rowtype; current_root gridex_received_sources.object_assessments%rowtype;\n review_snap gridex_received_sources.object_selection_snapshots%rowtype;\n cover jsonb:=p_business->''coverageWindow''; wire jsonb:=p_business->''wire''; reference jsonb:=p_business->''baselineCoverageAssessment'';\n root_entry jsonb; current_entry jsonb; epoch timestamptz; valid_start timestamptz; valid_end timestamptz;\n change_at timestamptz; minute text; market_time timestamp; owner_ok boolean;supply_basis jsonb;\nBEGIN\n SELECT * INTO src FROM gridex_received_sources.sources WHERE source_message_id=p_source_id AND company_id=(p_business->>''companyId'')::uuid\n AND environment=p_business->>''environment'' AND payload_hash=p_business->>''sourcePayloadHash'';\n IF NOT FOUND OR src.message_code<>''Z05'' OR src.source_received_at IS NULL THEN RETURN false; END IF;\n IF jsonb_typeof(p_business) IS DISTINCT FROM ''object''\n OR jsonb_typeof(cover) IS DISTINCT FROM ''object''\n OR jsonb_typeof(reference) IS DISTINCT FROM ''object''\n OR p_business->>''owner'' IS DISTINCT FROM ''reviewed-received-closure-v1''\n OR p_business->>''coverage'' IS DISTINCT FROM ''reviewed_post_ledger_closure''\n OR p_business->>''businessDisposition'' IS DISTINCT FROM ''reviewed''\n OR p_business->>''reviewStatement'' IS DISTINCT FROM ''original_supply_closure''\n OR p_business->>''graphNamespace'' IS DISTINCT FROM ''legacy_unqualified''\n OR p_business#>>''{object,identityAgency}'' IS DISTINCT FROM ''9''\n OR p_business-ARRAY[''version'',''owner'',''coverage'',''sourceDisposition'',''businessDisposition'',''graphNamespace'',''sourceMessageId'',''sourcePayloadHash'',''sourceReceivedAt'',''companyId'',''environment'',''object'',''assessedAt'',''wire'',''reviewerUserId'',''reviewStatement'',''customerId'',''meteringPointId'',''siteId'',''switchRequestId'',''supplyPeriodId'',''coverageWindow'',''baselineCurrentAssessmentId'',''reviewSnapshot'',''baselineCoverageAssessment'',''legacyEndDateProjection'']<>''{}''::jsonb\n OR NOT p_business ?& ARRAY[''version'',''owner'',''coverage'',''sourceDisposition'',''businessDisposition'',''graphNamespace'',''sourceMessageId'',''sourcePayloadHash'',''sourceReceivedAt'',''companyId'',''environment'',''object'',''assessedAt'',''wire'',''reviewerUserId'',''reviewStatement'',''customerId'',''meteringPointId'',''siteId'',''switchRequestId'',''supplyPeriodId'',''coverageWindow'',''baselineCurrentAssessmentId'',''reviewSnapshot'',''baselineCoverageAssessment'',''legacyEndDateProjection'']\n OR jsonb_typeof(p_business->''reviewSnapshot'') IS DISTINCT FROM ''object''\n OR (p_business->''reviewSnapshot'')-ARRAY[''snapshotId'',''readsetHash'',''cutoffAt'']<>''{}''::jsonb\n OR NOT p_business->''reviewSnapshot'' ?& ARRAY[''snapshotId'',''readsetHash'',''cutoffAt'']\n -- Handbok 26A p70 supplier handoff; LK is a conservative supported subset.\n OR substring(wire#>>''{effectiveTo,marketMinute}'',9,4) IS DISTINCT FROM ''0000''\n OR NOT gridex_received_sources.closure_wire_matches_v1(src.raw_payload,p_business->''object'',wire)\n OR NOT gridex_received_sources.review_party_proof_consistent(p_party,p_business,src.source_received_at)\n OR NOT EXISTS(SELECT FROM public.companies c WHERE c.id=src.company_id AND coalesce(c.status,''active'') IN (''active'',''onboarding''))\n OR NOT (public.gridex_actor_has_company_permission((p_business->>''reviewerUserId'')::uuid,src.company_id,''communication.write'')\n   OR public.gridex_actor_has_company_permission((p_business->>''reviewerUserId'')::uuid,src.company_id,''ediel_testing.write'')) THEN RETURN false; END IF;\n IF cover->>''kind'' IS DISTINCT FROM ''post_ledger_supply'' OR cover->>''supplyPeriodId'' IS DISTINCT FROM p_business->>''supplyPeriodId''\n OR cover->>''switchRequestId'' IS DISTINCT FROM p_business->>''switchRequestId''\n OR cover-ARRAY[''kind'',''baselineSourceMessageId'',''baselineAssessmentId'',''baselineFactsHash'',''supplyPeriodId'',''switchRequestId'',''switchCreatedAt'',''outboundSourceMessageId'',''outboundCreatedAt'',''validFrom'',''validTo'']<>''{}''::jsonb\n OR NOT cover ?& ARRAY[''kind'',''baselineSourceMessageId'',''baselineAssessmentId'',''baselineFactsHash'',''supplyPeriodId'',''switchRequestId'',''switchCreatedAt'',''outboundSourceMessageId'',''outboundCreatedAt'',''validFrom'',''validTo'']\n OR wire->''object'' IS DISTINCT FROM p_business->''object'' OR wire->>''messageCode'' IS DISTINCT FROM src.message_code\n OR wire->>''legalSender'' IS DISTINCT FROM p_party#>>''{parties,legalSender}'' OR wire->>''legalReceiver'' IS DISTINCT FROM p_party#>>''{parties,legalReceiver}''\n OR wire->>''transportSender'' IS DISTINCT FROM p_party#>>''{parties,transportSender}'' OR wire->>''transportReceiver'' IS DISTINCT FROM p_party#>>''{parties,transportReceiver}''\n THEN RETURN false; END IF;\n SELECT * INTO review_snap FROM gridex_received_sources.object_selection_snapshots\n WHERE id=(p_business#>>''{reviewSnapshot,snapshotId}'')::uuid AND company_id=src.company_id AND environment=src.environment\n AND readset_hash=p_business#>>''{reviewSnapshot,readsetHash}'' AND cutoff_at=(p_business#>>''{reviewSnapshot,cutoffAt}'')::timestamptz;\n IF NOT FOUND OR (review_snap.readset_text::jsonb->>''complete'') IS DISTINCT FROM ''true''\n OR review_snap.cutoff_at>(p_business->>''assessedAt'')::timestamptz\n OR NOT EXISTS(SELECT FROM jsonb_array_elements(review_snap.readset_text::jsonb->''sources'') item\n   WHERE item->>''sourceMessageId''=src.source_message_id::text AND item->>''payloadHash''=src.payload_hash) THEN RETURN false; END IF;\n SELECT opened_at INTO epoch FROM gridex_received_sources.epoch WHERE singleton;\n valid_start:=(cover->>''validFrom'')::timestamptz; valid_end:=(cover->>''validTo'')::timestamptz;\n minute:=wire#>>''{effectiveTo,marketMinute}'';\n IF minute IS NULL OR minute !~ ''^[0-9]{12}$'' OR substring(minute,1,4)::int<1 OR substring(minute,9,2)::int>23 OR substring(minute,11,2)::int>59 THEN RETURN false; END IF;\n market_time:=make_timestamp(substring(minute,1,4)::int,substring(minute,5,2)::int,substring(minute,7,2)::int,substring(minute,9,2)::int,substring(minute,11,2)::int,0);\n change_at:=market_time AT TIME ZONE ''Etc/GMT-1'';\n IF (wire#>>''{effectiveTo,utc}'')::timestamptz IS DISTINCT FROM change_at OR valid_start IS NULL OR NOT isfinite(valid_start)\n OR valid_start<epoch OR (valid_end IS NOT NULL AND (NOT isfinite(valid_end) OR valid_end<=valid_start))\n OR change_at<=valid_start OR (valid_end IS NOT NULL AND change_at<>valid_end)\n OR p_business->>''legacyEndDateProjection'' IS DISTINCT FROM market_time::date::text THEN RETURN false; END IF;\n SELECT * INTO baseline FROM gridex_received_sources.sources WHERE source_message_id=(cover->>''baselineSourceMessageId'')::uuid\n AND company_id=src.company_id AND environment=src.environment AND message_code=''Z04'';\n IF NOT FOUND OR baseline.source_message_id=src.source_message_id OR reference IS DISTINCT FROM jsonb_build_object(\n  ''sourceMessageId'',baseline.source_message_id,''assessmentId'',p_business->>''baselineCurrentAssessmentId'',\n  ''factsHash'',reference->>''factsHash'',''payloadHash'',baseline.payload_hash) THEN RETURN false; END IF;\n SELECT a.* INTO root FROM gridex_received_sources.object_assessments a JOIN gridex_received_sources.object_availability_witnesses w ON w.assessment_id=a.id\n WHERE a.id=(cover->>''baselineAssessmentId'')::uuid AND a.source_message_id=baseline.source_message_id AND a.company_id=src.company_id\n AND a.environment=src.environment AND a.facts_hash=cover->>''baselineFactsHash'' AND w.facts_hash=a.facts_hash AND w.observed_at<=review_snap.cutoff_at;\n IF NOT FOUND THEN RETURN false; END IF;\n SELECT value INTO root_entry FROM jsonb_array_elements(root.facts_text::jsonb->''objects'')\n WHERE value#>>''{object,objectId}''=p_business#>>''{object,objectId}'' AND value#>>''{object,identityAgency}''=''9'';\n IF root_entry->>''disposition'' IS DISTINCT FROM ''accepted'' OR root_entry#>>''{business,owner}'' IS DISTINCT FROM ''inbound-z04-switch-confirmation-v1''\n OR root.source_payload_hash IS DISTINCT FROM baseline.payload_hash\n OR root_entry#>>''{business,sourceMessageId}'' IS DISTINCT FROM baseline.source_message_id::text\n OR root_entry#>>''{business,sourcePayloadHash}'' IS DISTINCT FROM baseline.payload_hash\n OR root_entry#>>''{business,companyId}'' IS DISTINCT FROM src.company_id::text\n OR root_entry#>>''{business,environment}'' IS DISTINCT FROM src.environment\n OR root_entry#>>''{party,parties,legalSender}'' IS DISTINCT FROM wire->>''legalSender''\n OR root_entry#>>''{party,parties,legalReceiver}'' IS DISTINCT FROM wire->>''legalReceiver''\n OR root_entry#>>''{business,switchRequestId}'' IS DISTINCT FROM p_business->>''switchRequestId''\n OR root_entry#>>''{business,supplyPeriodId}'' IS DISTINCT FROM p_business->>''supplyPeriodId''\n OR root_entry#>>''{business,customerId}'' IS DISTINCT FROM p_business->>''customerId''\n OR root_entry#>>''{business,meteringPointId}'' IS DISTINCT FROM p_business->>''meteringPointId''\n OR root_entry#>>''{business,siteId}'' IS DISTINCT FROM p_business->>''siteId''\n OR (root_entry#>>''{business,effectiveFrom,utc}'')::timestamptz IS DISTINCT FROM valid_start THEN RETURN false; END IF;\n SELECT a.* INTO current_root FROM gridex_received_sources.object_assessments a JOIN gridex_received_sources.object_availability_witnesses w ON w.assessment_id=a.id\n WHERE a.id=(p_business->>''baselineCurrentAssessmentId'')::uuid AND a.source_message_id=baseline.source_message_id\n AND a.company_id=src.company_id AND a.environment=src.environment AND w.facts_hash=a.facts_hash AND w.observed_at<=review_snap.cutoff_at\n AND NOT EXISTS(SELECT FROM gridex_received_sources.object_assessments next WHERE next.previous_assessment_id=a.id);\n IF NOT FOUND THEN RETURN false; END IF;\n SELECT value INTO current_entry FROM jsonb_array_elements(current_root.facts_text::jsonb->''objects'')\n WHERE value#>>''{object,objectId}''=p_business#>>''{object,objectId}'' AND value#>>''{object,identityAgency}''=''9'';\n IF current_entry->>''disposition'' IS DISTINCT FROM ''accepted''\n OR current_entry#>>''{business,owner}'' IS DISTINCT FROM ''reviewed-received-structure-v1''\n OR current_entry#>>''{business,wire,messageCode}'' IS DISTINCT FROM ''Z04''\n OR current_entry#>''{business,wire,functionCode}'' NOT IN (''\"9\"''::jsonb,''null''::jsonb)\n OR current_entry#>''{business,replaces}'' IS DISTINCT FROM ''null''::jsonb\n OR current_entry#>''{business,coverageWindow}'' IS DISTINCT FROM cover\n OR current_root.facts_hash IS DISTINCT FROM reference->>''factsHash''\n OR current_root.source_payload_hash IS DISTINCT FROM baseline.payload_hash\n OR current_entry#>>''{business,sourceMessageId}'' IS DISTINCT FROM baseline.source_message_id::text\n OR current_entry#>>''{business,sourcePayloadHash}'' IS DISTINCT FROM baseline.payload_hash\n OR current_entry#>>''{business,companyId}'' IS DISTINCT FROM src.company_id::text\n OR current_entry#>>''{business,environment}'' IS DISTINCT FROM src.environment\n OR current_entry#>>''{business,customerId}'' IS DISTINCT FROM p_business->>''customerId''\n OR current_entry#>>''{business,meteringPointId}'' IS DISTINCT FROM p_business->>''meteringPointId''\n OR current_entry#>>''{business,siteId}'' IS DISTINCT FROM p_business->>''siteId''\n OR current_entry#>>''{business,switchRequestId}'' IS DISTINCT FROM p_business->>''switchRequestId''\n OR current_entry#>>''{business,supplyPeriodId}'' IS DISTINCT FROM p_business->>''supplyPeriodId''\n OR current_entry#>>''{business,wire,legalSender}'' IS DISTINCT FROM wire->>''legalSender''\n OR current_entry#>>''{business,wire,legalReceiver}'' IS DISTINCT FROM wire->>''legalReceiver''\n OR (current_entry#>>''{business,wire,effectiveFrom,utc}'')::timestamptz IS DISTINCT FROM valid_start\n THEN RETURN false; END IF;\n -- The retained snapshot must actually contain the current baseline assessment,\n -- rather than merely sharing a plausible time and tenant with it.\n IF NOT EXISTS(SELECT FROM jsonb_array_elements(review_snap.readset_text::jsonb->''sources'') source,\n  LATERAL jsonb_array_elements(source->''assessments'') assessment\n  WHERE source->>''sourceMessageId''=baseline.source_message_id::text AND source->>''payloadHash''=baseline.payload_hash\n  AND assessment->>''id''=root.id::text AND assessment->>''factsHash''=root.facts_hash\n  AND (assessment->>''availableAt'')::timestamptz<=review_snap.cutoff_at) THEN RETURN false; END IF;\n IF NOT EXISTS(SELECT FROM jsonb_array_elements(review_snap.readset_text::jsonb->''sources'') source,\n  LATERAL jsonb_array_elements(source->''assessments'') assessment\n  WHERE source->>''sourceMessageId''=baseline.source_message_id::text AND assessment->>''id''=current_root.id::text\n  AND assessment->>''factsHash''=current_root.facts_hash AND (assessment->>''availableAt'')::timestamptz<=review_snap.cutoff_at) THEN RETURN false; END IF;\n -- Selection may not choose a convenient reviewed root among ambiguous\n -- latest witnessed baselines for this same immutable supply and object.\n IF (SELECT count(*) FROM gridex_received_sources.object_assessments a\n  JOIN gridex_received_sources.object_availability_witnesses w ON w.assessment_id=a.id AND w.facts_hash=a.facts_hash\n  JOIN gridex_received_sources.sources source ON source.source_message_id=a.source_message_id\n  CROSS JOIN LATERAL jsonb_array_elements(a.facts_text::jsonb->''objects'') item\n  WHERE a.company_id=src.company_id AND a.environment=src.environment AND source.message_code=''Z04''\n  AND w.observed_at<=review_snap.cutoff_at\n  AND NOT EXISTS(SELECT FROM gridex_received_sources.object_assessments child WHERE child.previous_assessment_id=a.id)\n  AND item->>''disposition''=''accepted'' AND item#>>''{business,owner}''=''reviewed-received-structure-v1''\n  AND item#>>''{business,supplyPeriodId}''=p_business->>''supplyPeriodId''\n  AND item#>>''{object,objectId}''=p_business#>>''{object,objectId}'' AND item#>>''{object,identityAgency}''=''9''\n  AND item#>>''{business,wire,legalSender}''=wire->>''legalSender''\n  AND item#>>''{business,wire,legalReceiver}''=wire->>''legalReceiver'')<>1 THEN RETURN false; END IF;\n -- The current closing source and initial approved source form one immutable\n -- versioned relation. A legacy DATE/status row cannot reconstruct this tuple.\n supply_basis:=gridex_received_sources.supply_period_source_basis_v1(src.company_id,(p_business->>''supplyPeriodId'')::uuid,valid_start,change_at);\n IF supply_basis IS NULL OR supply_basis->>''qualified'' IS DISTINCT FROM ''true''\n  OR supply_basis->>''companyId'' IS DISTINCT FROM src.company_id::text OR supply_basis->>''periodId'' IS DISTINCT FROM p_business->>''supplyPeriodId''\n  OR supply_basis->>''switchId'' IS DISTINCT FROM p_business->>''switchRequestId''\n  OR supply_basis->>''initialSourceMessageId'' IS DISTINCT FROM baseline.source_message_id::text\n  OR supply_basis->>''sourceMessageId'' IS DISTINCT FROM src.source_message_id::text\n  OR supply_basis->>''customerId'' IS DISTINCT FROM p_business->>''customerId'' OR supply_basis->>''meteringPointId'' IS DISTINCT FROM p_business->>''meteringPointId''\n  OR supply_basis->>''siteId'' IS DISTINCT FROM p_business->>''siteId'' OR supply_basis->>''dsoEdielId'' IS DISTINCT FROM wire->>''legalSender''\n  OR (supply_basis->>''marketStartAt'')::timestamptz IS DISTINCT FROM valid_start OR (supply_basis->>''marketEndAt'')::timestamptz IS DISTINCT FROM change_at\n  OR supply_basis->>''originalMessageId'' IS DISTINCT FROM cover->>''outboundSourceMessageId''\n  OR jsonb_array_length(supply_basis->''sourceObjects'') IS DISTINCT FROM 1\n  OR supply_basis#>>''{sourceObjects,0,point}'' IS DISTINCT FROM p_business#>>''{object,objectId}''\n  OR supply_basis#>>''{sourceObjects,0,identityAgency}'' IS DISTINCT FROM p_business#>>''{object,identityAgency}'' THEN RETURN false;END IF;\n SELECT EXISTS(SELECT FROM public.supplier_switch_requests sw\n JOIN public.customer_supply_periods sp ON sp.id=(p_business->>''supplyPeriodId'')::uuid\n JOIN public.ediel_messages outbound ON outbound.id=sw.outbound_z03_message_id\n JOIN public.metering_points mp ON mp.id=sw.metering_point_id JOIN public.customer_sites cs ON cs.id=sw.site_id\n WHERE sw.id=(p_business->>''switchRequestId'')::uuid AND sw.company_id=src.company_id AND sp.company_id=src.company_id\n AND sw.inbound_z04_message_id=baseline.source_message_id AND sp.source_message_id=baseline.source_message_id AND sp.source_end_message_id=src.source_message_id\n AND sw.rff_li_reference=current_entry#>>''{business,wire,caseReference}''\n AND sw.metering_point_id=(p_business->>''meteringPointId'')::uuid AND sp.metering_point_id=sw.metering_point_id\n AND sw.customer_id=(p_business->>''customerId'')::uuid AND sp.customer_id=sw.customer_id AND sw.site_id=(p_business->>''siteId'')::uuid\n AND (sp.source_switch_request_id IS NULL OR sp.source_switch_request_id=sw.id)\n AND mp.company_id=src.company_id AND cs.company_id=src.company_id AND mp.site_id=cs.id AND mp.customer_id=sw.customer_id AND cs.customer_id=sw.customer_id\n AND sw.confirmed_start_date=sp.start_date\n AND sp.end_date=market_time::date\n AND sw.created_at=(cover->>''switchCreatedAt'')::timestamptz AND sw.created_at>=epoch AND sw.created_at<=valid_start\n AND outbound.id=(cover->>''outboundSourceMessageId'')::uuid AND outbound.company_id=src.company_id AND outbound.environment=src.environment\n AND outbound.direction=''outbound'' AND outbound.message_standard=''edifact'' AND outbound.message_family=''PRODAT'' AND outbound.message_code=''Z03''\n AND outbound.created_at=(cover->>''outboundCreatedAt'')::timestamptz AND outbound.created_at>=sw.created_at AND outbound.created_at<=review_snap.cutoff_at\n AND (supply_basis->>''originalAcceptedAt'')::timestamptz>=outbound.created_at AND (supply_basis->>''originalAcceptedAt'')::timestamptz<=baseline.source_received_at\n AND outbound.customer_id=sw.customer_id AND outbound.metering_point_id=sw.metering_point_id AND outbound.site_id=sw.site_id) INTO owner_ok;\n IF owner_ok IS DISTINCT FROM true THEN RETURN false; END IF;\n RETURN true;\nEXCEPTION WHEN invalid_text_representation OR invalid_datetime_format OR datetime_field_overflow OR numeric_value_out_of_range OR invalid_parameter_value THEN RETURN false;\nEND ","source_line":28300,"source_statement_sha256":"5b2991d207e76763ec67b3253a868d5b790eed13a7b4d1c647f4c694bcbf4bfc","expected":{"owner":"postgres","acl":"{postgres=X/postgres}","proconfig":["search_path=pg_catalog","TimeZone=UTC"],"provolatile":"s","prosecdef":true,"proisstrict":false,"proleakproof":false,"proparallel":"u","procost":100,"prorows":0,"proargnames":["p_party","p_business","p_source_id"],"proargmodes":null,"return_type":"boolean","proretset":false,"identity_arguments":"p_party jsonb, p_business jsonb, p_source_id uuid","arguments":"p_party jsonb, p_business jsonb, p_source_id uuid","language":"plpgsql"}},{"signature":"public.activate_customer_supply_v1(uuid,uuid,uuid,date,uuid,text)","before":"85561284bde4891c22cfd8f5f640e342","after":"f37f78094a23b8ec93bf6db4bdf4ac58","canonical_complete":"f37f78094a23b8ec93bf6db4bdf4ac58","original":"\ndeclare\n  v_switch public.supplier_switch_requests%rowtype;\n  v_period_id uuid;\n  v_contract_id uuid;\n  v_application_id uuid;\n  v_workflow public.customer_application_workflows%rowtype;\n  v_event_id uuid;\n  v_job_id uuid;\n  v_start_date date;\n  v_key text;\n  v_now timestamptz := now();\n  v_tenant_reference text;\nbegin\n  if p_company_id is null then\n    raise exception ''supply_activation_company_required'' using errcode = ''22023'';\n  end if;\n  if p_supplier_switch_request_id is null then\n    raise exception ''supply_activation_switch_required'' using errcode = ''22023'';\n  end if;\n  if p_source_message_id is null then\n    raise exception ''supply_activation_source_message_required'' using errcode = ''22023'';\n  end if;\n\n  select * into v_switch\n  from public.supplier_switch_requests\n  where id = p_supplier_switch_request_id\n    and company_id = p_company_id\n  for update;\n\n  if not found then\n    raise exception ''supply_activation_switch_not_found'' using errcode = ''P0002'';\n  end if;\n  if v_switch.customer_id is null then\n    raise exception ''supply_activation_customer_required'' using errcode = ''23502'';\n  end if;\n  if v_switch.metering_point_id is null then\n    raise exception ''supply_activation_metering_point_required'' using errcode = ''23502'';\n  end if;\n\n  v_contract_id := coalesce(v_switch.contract_id, v_switch.customer_contract_id);\n  if v_contract_id is null then\n    raise exception ''supply_activation_contract_required'' using errcode = ''23502'';\n  end if;\n  if v_switch.status not in (\n    ''confirmed'',\n    ''accepted'',\n    ''completed''\n  ) then\n    raise exception ''supply_activation_switch_not_confirmed'' using errcode = ''23514'';\n  end if;\n\n  if not exists(\n    select 1\n    from public.customer_contracts cc\n    join public.metering_points mp\n      on mp.id=v_switch.metering_point_id\n     and mp.company_id=cc.company_id\n     and mp.customer_id=cc.customer_id\n    left join public.customer_sites cs\n      on cs.id=coalesce(v_switch.customer_site_id,v_switch.site_id)\n     and cs.company_id=cc.company_id\n     and cs.customer_id=cc.customer_id\n    where cc.id=v_contract_id\n      and cc.company_id=p_company_id\n      and cc.customer_id=v_switch.customer_id\n      and (\n        coalesce(v_switch.customer_site_id,v_switch.site_id) is null\n        or cs.id is not null\n      )\n  ) then\n    raise exception using\n      errcode=''23514'',\n      message=''supply_activation_customer_contract_site_meter_mismatch'';\n  end if;\n\n  v_start_date := coalesce(\n    p_actual_start_date,\n    v_switch.confirmed_start_date,\n    v_switch.requested_start_date\n  );\n  if v_start_date is null then\n    raise exception ''supply_activation_start_date_required'' using errcode = ''23502'';\n  end if;\n  v_key := coalesce(\n    nullif(btrim(p_idempotency_key), ''''),\n    format(''activate_customer_supply_v1:%s:%s'', p_company_id, p_supplier_switch_request_id)\n  );\n\n  insert into public.customer_supply_periods(\n    company_id,\n    customer_id,\n    metering_point_id,\n    contract_id,\n    start_date,\n    actual_start_date,\n    source,\n    source_process,\n    source_message_id,\n    source_switch_request_id,\n    status,\n    metadata,\n    updated_at\n  ) values (\n    p_company_id,\n    v_switch.customer_id,\n    v_switch.metering_point_id,\n    v_contract_id,\n    v_start_date,\n    v_start_date,\n    ''activate_customer_supply_v1'',\n    ''supplier_switch_confirmation'',\n    p_source_message_id,\n    v_switch.id,\n    ''active'',\n    jsonb_build_object(\n      ''activation_idempotency_key'', v_key,\n      ''activated_at'', v_now\n    ),\n    v_now\n  )\n  on conflict (company_id, metering_point_id, start_date)\n    where status in (''active'', ''confirmed_by_grid_owner'')\n  do update set\n    customer_id = excluded.customer_id,\n    contract_id = excluded.contract_id,\n    actual_start_date = coalesce(public.customer_supply_periods.actual_start_date, excluded.actual_start_date),\n    source_message_id = excluded.source_message_id,\n    source_switch_request_id = excluded.source_switch_request_id,\n    status = ''active'',\n    metadata = coalesce(public.customer_supply_periods.metadata, ''{}''::jsonb)\n      || excluded.metadata,\n    updated_at = excluded.updated_at\n  returning id into v_period_id;\n\n  update public.supplier_switch_requests\n  set status = ''completed'',\n      confirmed_start_date = coalesce(confirmed_start_date, v_start_date),\n      completed_at = coalesce(completed_at, v_now),\n      external_reference = coalesce(external_reference, v_key),\n      inbound_z04_message_id = coalesce(inbound_z04_message_id, p_source_message_id),\n      lifecycle_blocked = false,\n      lifecycle_block_source = null,\n      updated_at = v_now\n  where id = v_switch.id\n    and company_id = p_company_id;\n\n  update public.customer_contracts\n  set status = ''active'',\n      lifecycle_stage = ''active'',\n      actual_start_date = coalesce(actual_start_date, v_start_date),\n      confirmed_start_date = coalesce(confirmed_start_date, v_start_date),\n      billing_eligible_at = coalesce(billing_eligible_at, v_now),\n      billing_eligibility_source = coalesce(\n        billing_eligibility_source,\n        ''activate_customer_supply_v1''\n      ),\n      metadata = coalesce(metadata, ''{}''::jsonb) || jsonb_build_object(\n        ''supply_period_id'', v_period_id,\n        ''supplier_switch_request_id'', v_switch.id,\n        ''activation_source_message_id'', p_source_message_id\n      ),\n      updated_at = v_now\n  where id = v_contract_id\n    and company_id = p_company_id\n    and customer_id = v_switch.customer_id\n    and status in (''signed'', ''active'');\n\n  if not found then\n    raise exception ''supply_activation_contract_not_activatable'' using errcode = ''23514'';\n  end if;\n\n  select workflow.* into v_workflow\n  from public.customer_application_workflows workflow\n  where workflow.company_id = p_company_id\n    and workflow.customer_id = v_switch.customer_id\n    and workflow.contract_id = v_contract_id\n  order by created_at desc\n  limit 1\n  for update;\n\n  if found then\n    v_application_id := v_workflow.customer_application_id;\n\n    insert into public.customer_application_workflow_events(\n      company_id,\n      workflow_id,\n      customer_application_id,\n      operation_id,\n      from_state,\n      to_state,\n      event_code,\n      actor_user_id,\n      metadata,\n      idempotency_key\n    ) values (\n      p_company_id,\n      v_workflow.id,\n      v_workflow.customer_application_id,\n      v_workflow.operation_id,\n      v_workflow.state,\n      ''completed'',\n      ''workflow.supply_activated'',\n      p_actor_user_id,\n      jsonb_build_object(\n        ''supply_period_id'', v_period_id,\n        ''supplier_switch_request_id'', v_switch.id,\n        ''actual_start_date'', v_start_date\n      ),\n      v_key || '':workflow''\n    )\n    on conflict (company_id, idempotency_key) do nothing;\n\n    update public.customer_application_workflows\n    set state = ''completed'',\n        next_action = ''none'',\n        completed_at = coalesce(completed_at, v_now),\n        last_transition_at = v_now,\n        workflow_version = case\n          when state = ''completed'' then workflow_version\n          else workflow_version + 1\n        end,\n        snapshot = coalesce(snapshot, ''{}''::jsonb) || jsonb_build_object(\n          ''supply_period_id'', v_period_id,\n          ''supplier_switch_request_id'', v_switch.id,\n          ''actual_start_date'', v_start_date,\n          ''billing_eligible_at'', v_now,\n          ''next_action'', ''none''\n        ),\n        updated_at = v_now\n    where id = v_workflow.id;\n\n    update public.website_customer_applications\n    set status = ''active'',\n        actual_start_date = coalesce(actual_start_date, v_start_date),\n        next_step = ''none'',\n        updated_at = v_now\n    where id = v_application_id\n      and company_id = p_company_id;\n  end if;\n\n  insert into public.domain_events(\n    company_id,\n    event_type,\n    aggregate_type,\n    aggregate_id,\n    subject_customer_id,\n    actor_user_id,\n    source,\n    idempotency_key,\n    payload,\n    occurred_at\n  ) values (\n    p_company_id,\n    ''supply.started'',\n    ''customer_supply_period'',\n    v_period_id::text,\n    v_switch.customer_id,\n    p_actor_user_id,\n    ''activate_customer_supply_v1'',\n    v_key || '':domain_event'',\n    jsonb_build_object(\n      ''customer_id'', v_switch.customer_id,\n      ''contract_id'', v_contract_id,\n      ''customer_site_id'', coalesce(v_switch.customer_site_id, v_switch.site_id),\n      ''metering_point_id'', v_switch.metering_point_id,\n      ''supplier_switch_request_id'', v_switch.id,\n      ''supply_period_id'', v_period_id,\n      ''actual_start_date'', v_start_date,\n      ''billing_eligible_at'', v_now\n    ),\n    v_now\n  )\n  on conflict (idempotency_key) where idempotency_key is not null\n  do nothing\n  returning id into v_event_id;\n\n  if v_event_id is null then\n    select id into v_event_id\n    from public.domain_events\n    where idempotency_key = v_key || '':domain_event'';\n  end if;\n\n  insert into public.customer_operation_jobs(\n    company_id,\n    customer_id,\n    customer_site_id,\n    metering_point_id,\n    job_type,\n    status,\n    priority,\n    idempotency_key,\n    payload,\n    request_snapshot,\n    run_after,\n    created_by,\n    updated_at\n  ) values (\n    p_company_id,\n    v_switch.customer_id,\n    coalesce(v_switch.customer_site_id, v_switch.site_id),\n    v_switch.metering_point_id,\n    ''dispatch_lifecycle_notification'',\n    ''queued'',\n    40,\n    ''lifecycle_notification:'' || v_key || '':customer.welcome_active'',\n    jsonb_build_object(\n      ''event_type'', ''supply_period.activated'',\n      ''source_event_id'', v_event_id,\n      ''contract_id'', v_contract_id,\n      ''payload'', jsonb_build_object(\n        ''start_date'', v_start_date,\n        ''supply_period_id'', v_period_id\n      )\n    ),\n    jsonb_build_object(\n      ''domain_event_id'', v_event_id,\n      ''supplier_switch_request_id'', v_switch.id\n    ),\n    v_now,\n    p_actor_user_id,\n    v_now\n  )\n  on conflict do nothing\n  returning id into v_job_id;\n\n  if v_job_id is null then\n    select id into v_job_id\n    from public.customer_operation_jobs\n    where company_id = p_company_id\n      and job_type = ''dispatch_lifecycle_notification''\n      and idempotency_key = ''lifecycle_notification:'' || v_key || '':customer.welcome_active''\n    order by created_at desc\n    limit 1;\n  end if;\n\n  select external_tenant_reference into v_tenant_reference\n  from public.companies\n  where id = p_company_id;\n\n  insert into public.webhook_deliveries(\n    company_id,\n    webhook_subscription_id,\n    domain_event_id,\n    event_type,\n    max_attempts,\n    target_url,\n    idempotency_key,\n    payload\n  )\n  select\n    p_company_id,\n    subscription.id,\n    v_event_id,\n    ''supply.started'',\n    subscription.max_attempts,\n    subscription.endpoint_url,\n    format(''webhook:%s:%s'', subscription.id, v_event_id),\n    jsonb_build_object(\n      ''id'', v_event_id,\n      ''type'', ''supply.started'',\n      ''event_id'', v_event_id,\n      ''event_type'', ''supply.started'',\n      ''created_at'', v_now,\n      ''tenant_reference'', v_tenant_reference,\n      ''customer_id'', v_switch.customer_id,\n      ''aggregate'', jsonb_build_object(\n        ''type'', ''customer_supply_period'',\n        ''id'', v_period_id\n      ),\n      ''data'', jsonb_build_object(\n        ''contract_id'', v_contract_id,\n        ''supplier_switch_request_id'', v_switch.id,\n        ''supply_period_id'', v_period_id,\n        ''actual_start_date'', v_start_date\n      )\n    )\n  from public.webhook_subscriptions subscription\n  where subscription.company_id = p_company_id\n    and subscription.status = ''active''\n    and (\n      ''*'' = any(coalesce(subscription.event_types, ''{}''::text[]))\n      or ''supply.started'' = any(coalesce(subscription.event_types, ''{}''::text[]))\n    )\n  on conflict (idempotency_key) do nothing;\n\n  return query select\n    v_switch.id,\n    v_period_id,\n    v_contract_id,\n    v_application_id,\n    v_workflow.id,\n    v_event_id,\n    v_job_id;\nend;\n","patched":"\nDECLARE proof gridex_received_sources.normal_switch_confirmations%rowtype;prior gridex_received_sources.normal_supply_activations%rowtype;\n p public.customer_supply_periods%rowtype;s public.supplier_switch_requests%rowtype;m public.ediel_messages%rowtype;origin public.ediel_messages%rowtype;c public.customer_contracts%rowtype;result jsonb;\nBEGIN\n PERFORM gridex_bilateral_prodat.lock_supply_v1();\n PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;\n PERFORM cm.user_id FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id FOR SHARE;\n IF p_actor_user_id IS NULL OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status=''active'') OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id AND cm.status=''active'' AND cm.is_active AND cm.accepted_at IS NOT NULL) OR public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,''metering.write'') IS NOT TRUE THEN RAISE EXCEPTION ''normal_supply_activation_actor_forbidden'' USING ERRCODE=''42501'';END IF;\n SELECT * INTO proof FROM gridex_received_sources.normal_switch_confirmations WHERE company_id=p_company_id AND switch_id=p_supplier_switch_request_id AND source_message_id=p_source_message_id;\n IF NOT FOUND THEN RAISE EXCEPTION ''normal_supply_activation_immutable_confirmation_required'';END IF;\n IF gridex_bilateral_prodat.recorded_supply_current_v1(p_company_id,proof.source_message_id) IS NOT TRUE THEN RAISE EXCEPTION ''bilateral_supply_activation_recorded_profile_required'';END IF;\n PERFORM z.id FROM public.ediel_messages z WHERE z.company_id=p_company_id AND z.id=ANY(ARRAY[proof.source_message_id,proof.original_message_id]) ORDER BY z.id FOR UPDATE;\n SELECT * INTO m FROM public.ediel_messages WHERE id=proof.source_message_id AND company_id=p_company_id;\n IF NOT EXISTS(SELECT FROM gridex_received_sources.supply_source_transitions tr WHERE tr.source_message_id=m.id AND tr.company_id=p_company_id AND tr.payload_hash=encode(sha256(convert_to(m.raw_payload,''UTF8'')),''hex'') AND proof.switch_id=ANY(tr.qualified_switch_ids)) THEN RAISE EXCEPTION ''normal_supply_activation_source_changed'';END IF;\n SELECT * INTO prior FROM gridex_received_sources.normal_supply_activations WHERE period_id=proof.period_id;\n IF FOUND THEN\n  -- Established own activation is returned before today''s profile, contract,\n  -- deadline or rule decisions. It cannot authorize a second market effect.\n  RETURN QUERY SELECT (prior.result->>''supplier_switch_request_id'')::uuid,(prior.result->>''supply_period_id'')::uuid,(prior.result->>''contract_id'')::uuid,(prior.result->>''customer_application_id'')::uuid,(prior.result->>''workflow_id'')::uuid,(prior.result->>''domain_event_id'')::uuid,(prior.result->>''notification_job_id'')::uuid;RETURN;\n END IF;\n PERFORM public.ediel_require_contract_records_available_v1(p_company_id,proof.contract_id);PERFORM public.ediel_require_source_bytes_available_v1(p_company_id,proof.source_message_id);PERFORM public.ediel_require_source_bytes_available_v1(p_company_id,proof.original_message_id);PERFORM gridex_ediel_inbound_context.require_v1(p_company_id,m.id);\n PERFORM gridex_ediel_source_rules.require_v1(p_company_id,m.id);\n IF proof.market_start_at>now() THEN RAISE EXCEPTION ''normal_supply_activation_not_due'';END IF;\n SELECT * INTO origin FROM public.ediel_messages WHERE id=proof.original_message_id AND company_id=p_company_id AND environment=m.environment;\n SELECT * INTO s FROM public.supplier_switch_requests WHERE id=proof.switch_id AND company_id=p_company_id FOR UPDATE;\n SELECT * INTO p FROM public.customer_supply_periods WHERE id=proof.period_id AND company_id=p_company_id FOR UPDATE;\n SELECT * INTO c FROM public.customer_contracts WHERE id=proof.contract_id AND company_id=p_company_id FOR SHARE;\n PERFORM profile.id FROM public.tenant_ediel_profiles profile WHERE profile.company_id=p_company_id AND profile.environment=m.environment ORDER BY profile.id FOR SHARE;\n PERFORM role.id FROM public.tenant_actor_roles role WHERE role.company_id=p_company_id AND role.environment=m.environment ORDER BY role.id FOR SHARE;\n PERFORM identifier.id FROM public.tenant_actor_identifiers identifier WHERE identifier.company_id=p_company_id AND identifier.environment=m.environment ORDER BY identifier.id FOR SHARE;\n IF NOT EXISTS(SELECT FROM public.tenant_ediel_profiles profile WHERE profile.company_id=p_company_id AND profile.environment=m.environment AND profile.market=''electricity'' AND profile.is_enabled AND profile.valid_from<=now() AND (profile.valid_to IS NULL OR now()<profile.valid_to))\n  OR NOT EXISTS(SELECT FROM public.tenant_actor_roles role WHERE role.company_id=p_company_id AND role.environment=m.environment AND role.actor_id::text=proof.legal_context->>''legalActorId'' AND role.role_code=''electricity_supplier'' AND role.valid_from<=now() AND (role.valid_to IS NULL OR now()<role.valid_to))\n  OR (SELECT count(DISTINCT (identifier.actor_id,identifier.identifier_value)) FROM public.tenant_actor_identifiers identifier WHERE identifier.company_id=p_company_id AND identifier.environment=m.environment AND identifier.identifier_type=''EdielId'' AND identifier.valid_from<=now() AND (identifier.valid_to IS NULL OR now()<identifier.valid_to))<>1\n  OR NOT EXISTS(SELECT FROM public.tenant_actor_identifiers identifier WHERE identifier.company_id=p_company_id AND identifier.environment=m.environment AND identifier.actor_id::text=proof.legal_context->>''legalActorId'' AND identifier.identifier_type=''EdielId'' AND identifier.identifier_value=proof.legal_context->>''legalEdielId'' AND identifier.valid_from<=now() AND (identifier.valid_to IS NULL OR now()<identifier.valid_to)) THEN RAISE EXCEPTION ''normal_supply_activation_current_legal_actor_required'';END IF;\n IF origin.direction IS DISTINCT FROM ''outbound'' OR gridex_received_sources.sent_source_is_current_v1(origin) IS NOT TRUE OR origin.immutable_rendered_at IS NULL OR origin.immutable_payload_hash IS DISTINCT FROM proof.original_payload_hash OR origin.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(origin.raw_payload,''UTF8'')),''hex'')\n  OR p.status IS DISTINCT FROM ''confirmed_by_grid_owner'' OR p.market_state_version IS DISTINCT FROM (proof.confirmed_period->>''market_state_version'')::bigint OR p.market_start_at IS DISTINCT FROM proof.market_start_at\n  OR p.source_message_id IS DISTINCT FROM proof.source_message_id OR p.source_switch_request_id IS DISTINCT FROM proof.switch_id OR p.customer_id IS DISTINCT FROM (proof.confirmed_period->>''customer_id'')::uuid OR p.metering_point_id IS DISTINCT FROM (proof.confirmed_period->>''metering_point_id'')::uuid OR p.market_end_at IS NOT NULL OR p.metadata IS DISTINCT FROM proof.confirmed_period->''metadata''\n  OR s.status IS DISTINCT FROM ''accepted'' OR s.inbound_z04_message_id IS DISTINCT FROM proof.source_message_id OR s.outbound_z03_message_id IS DISTINCT FROM proof.original_message_id OR s.lifecycle_blocked OR s.customer_id IS DISTINCT FROM p.customer_id OR s.metering_point_id IS DISTINCT FROM p.metering_point_id\n  OR s.contract_id IS DISTINCT FROM (proof.confirmed_switch->>''contract_id'')::uuid OR s.customer_contract_id IS DISTINCT FROM (proof.confirmed_switch->>''customer_contract_id'')::uuid OR s.site_id IS DISTINCT FROM (proof.confirmed_switch->>''site_id'')::uuid OR s.customer_site_id IS DISTINCT FROM (proof.confirmed_switch->>''customer_site_id'')::uuid\n  OR p.contract_id IS DISTINCT FROM (proof.confirmed_period->>''contract_id'')::uuid OR p.customer_contract_id IS DISTINCT FROM (proof.confirmed_period->>''customer_contract_id'')::uuid\n  OR c.id IS NULL OR c.customer_id IS DISTINCT FROM p.customer_id OR c.metering_point_id IS DISTINCT FROM p.metering_point_id OR (c.status IN(''signed'',''active'')) IS NOT TRUE OR gridex_received_sources.production_contract_hash_v1(c) IS DISTINCT FROM proof.protected_contract_hash\n  OR (p_actual_start_date IS NOT NULL AND p_actual_start_date IS DISTINCT FROM p.start_date) THEN RAISE EXCEPTION ''normal_supply_activation_current_confirmation_changed'';END IF;\n SELECT to_jsonb(effect) INTO result FROM gridex_received_sources.activate_supply_before_source_guard_v1(p_company_id,proof.switch_id,proof.source_message_id,p.start_date,p_actor_user_id,''ediel-normal-activation:''||proof.period_id) effect;\n IF result->>''supply_period_id'' IS DISTINCT FROM proof.period_id::text THEN RAISE EXCEPTION ''normal_supply_activation_period_replaced'';END IF;\n INSERT INTO gridex_received_sources.normal_supply_activations(period_id,company_id,source_message_id,actor_user_id,previous_period,resulting_period,result)\n SELECT proof.period_id,p_company_id,proof.source_message_id,p_actor_user_id,to_jsonb(p),to_jsonb(current),result FROM public.customer_supply_periods current WHERE current.id=proof.period_id AND current.company_id=p_company_id;\n RETURN QUERY SELECT (result->>''supplier_switch_request_id'')::uuid,(result->>''supply_period_id'')::uuid,(result->>''contract_id'')::uuid,(result->>''customer_application_id'')::uuid,(result->>''workflow_id'')::uuid,(result->>''domain_event_id'')::uuid,(result->>''notification_job_id'')::uuid;\nEND ","source_line":35701,"source_statement_sha256":"7439f832f685f04ab0d24f9e0c2148d6bb7fd08c285eb7ae6ce0de0ad6a05bc4","expected":{"owner":"postgres","acl":"{postgres=X/postgres,service_role=X/postgres}","proconfig":["search_path=public"],"provolatile":"v","prosecdef":true,"proisstrict":false,"proleakproof":false,"proparallel":"u","procost":100,"prorows":1000,"proargnames":["p_company_id","p_supplier_switch_request_id","p_source_message_id","p_actual_start_date","p_actor_user_id","p_idempotency_key","supplier_switch_request_id","supply_period_id","contract_id","customer_application_id","workflow_id","domain_event_id","notification_job_id"],"proargmodes":"{i,i,i,i,i,i,t,t,t,t,t,t,t}","return_type":"record","proretset":true,"identity_arguments":"p_company_id uuid, p_supplier_switch_request_id uuid, p_source_message_id uuid, p_actual_start_date date, p_actor_user_id uuid, p_idempotency_key text","arguments":"p_company_id uuid, p_supplier_switch_request_id uuid, p_source_message_id uuid, p_actual_start_date date DEFAULT NULL::date, p_actor_user_id uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text","language":"plpgsql"}},{"signature":"gridex_outbound_dispatch.mutate_v1(jsonb)","before":"a16d6877219da4418ec36e2258543ca9","after":"56e049dc8dcb43ef279e2dbf4b8f8736","canonical_complete":"56e049dc8dcb43ef279e2dbf4b8f8736","original":"\nDECLARE\n c uuid:=(p_input->>''companyId'')::uuid; env text:=p_input->>''environment''; actor uuid:=(p_input->>''actorUserId'')::uuid;\n mid uuid:=(p_input->>''messageId'')::uuid; aid uuid:=(p_input->>''attemptId'')::uuid; action text:=p_input->>''action'';\n m public.ediel_messages%rowtype; a gridex_outbound_dispatch.attempts%rowtype; r gridex_outbound_dispatch.reservations%rowtype;\n o gridex_outbound_dispatch.originals%rowtype; e gridex_outbound_dispatch.events%rowtype;\n tokens jsonb; owner jsonb:=p_input->''owner''; binding jsonb:=p_input->''binding''; result jsonb:=p_input->''result'';\n scoped boolean; event_kind text; body jsonb; classification text; bytes bytea;\nBEGIN\n IF action=''prepare'' THEN\n  -- Canonical DB row owns eligibility. Caller subtype, status and hash cannot opt out.\n  SELECT * INTO m FROM public.ediel_messages WHERE id=mid AND company_id=c AND environment=env FOR SHARE;\n  IF NOT FOUND THEN RAISE EXCEPTION ''outbound_dispatch_message_unavailable'' USING ERRCODE=''42501''; END IF;\n  SELECT * INTO o FROM gridex_outbound_dispatch.originals WHERE message_id=mid;\n  tokens:=gridex_received_sources.closure_wire_tokens_v1(m.raw_payload);\n  scoped:=o.message_id IS NOT NULL OR (m.direction=''outbound'' AND (\n   m.message_code=''Z08'' OR (m.message_family=''PRODAT'' AND (tokens IS NULL OR NOT EXISTS(\n    SELECT FROM jsonb_array_elements(tokens) t WHERE t->>''tag''=''BGM'')))\n   OR EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>''tag''=''BGM'' AND t#>>''{elements,1,0}''=''Z08'')));\n  -- A canonical LK wire remains outside this H checkpoint. A caller subtype\n  -- cannot hide Z25/H bytes behind a different profile.\n  IF o.message_id IS NULL AND m.direction=''outbound'' AND m.message_family=''PRODAT''\n   AND m.message_code=''Z08'' AND m.rule_profile_key=''PRODAT:Z08:LK:26.A:r3''\n   AND EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>''tag''=''BGM'' AND t#>>''{elements,1,0}''=''Z08'')\n   AND EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>''tag''=''CAV'' AND t#>>''{elements,1,0}''=''Z23'')\n   AND NOT EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>''tag''=''CAV'' AND t#>>''{elements,1,0}''=''Z25'')\n  THEN RETURN jsonb_build_object(''scoped'',false,''unscopedReason'',''canonical_lk_exemption''); END IF;\n  IF NOT coalesce(scoped,false) THEN RETURN jsonb_build_object(''scoped'',false); END IF;\n IF c IS NULL OR actor IS NULL OR mid IS NULL OR env IS NULL OR env NOT IN (''test'',''production'')\n OR NOT coalesce(public.gridex_actor_has_company_permission(actor,c,''communication.send''),false)\n OR NOT EXISTS(SELECT FROM public.user_profiles WHERE id=actor AND user_status=''active'')\n OR NOT EXISTS(SELECT FROM public.company_memberships WHERE company_id=c AND user_id=actor AND status=''active'' AND is_active AND accepted_at IS NOT NULL)\n OR NOT EXISTS(SELECT FROM public.canonical_tenant_operation_decision(c,CASE env WHEN ''production'' THEN ''ediel.production.send'' ELSE ''ediel.test.process'' END) d WHERE d.allowed)\n THEN RAISE EXCEPTION ''outbound_dispatch_actor_unavailable'' USING ERRCODE=''42501''; END IF;\n\n  IF m.direction IS DISTINCT FROM ''outbound'' OR m.message_standard IS DISTINCT FROM ''edifact'' OR m.message_family IS DISTINCT FROM ''PRODAT''\n  OR m.raw_payload IS NULL OR m.immutable_rendered_at IS NULL OR m.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,''UTF8'')),''hex'')\n  OR octet_length(m.raw_payload)>262144 OR m.rule_profile_key IS DISTINCT FROM ''PRODAT:Z08:H:26.A:r3''\n  OR NOT EXISTS(SELECT FROM public.ediel_message_profiles p JOIN public.ediel_rule_packs pack ON pack.id=p.rule_pack_id\n    WHERE p.id=m.rule_profile_version_id AND p.profile_key=m.rule_profile_key AND p.is_enabled AND pack.id=m.canonical_rule_pack_id\n    AND pack.status=''active'' AND pack.valid_from<=current_date AND (pack.valid_to IS NULL OR pack.valid_to>=current_date)\n    AND pack.family=''PRODAT'' AND pack.guide_version=''26.A'' AND pack.guide_revision=''3''\n    AND pack.source_hash=m.rule_pack_checksum AND m.rule_profile_version=pack.guide_version||'':r''||pack.guide_revision)\n  OR NOT EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>''tag''=''BGM'' AND t#>>''{elements,1,0}''=''Z08'')\n  OR NOT EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>''tag''=''CAV'' AND t#>>''{elements,1,0}''=''Z25''\n   AND tokens->((t->>''index'')::integer-1)->>''tag''=''CCI'' AND tokens->((t->>''index'')::integer-1)#>>''{elements,2,0}''=''Z13'')\n  THEN RAISE EXCEPTION ''outbound_dispatch_sealed_original_unavailable'' USING ERRCODE=''23514''; END IF;\n  IF aid IS NULL OR jsonb_typeof(owner) IS DISTINCT FROM ''object'' OR owner->>''kind'' IS NULL OR owner->>''kind'' NOT IN (''direct'',''worker'')\n  OR jsonb_typeof(binding) IS DISTINCT FROM ''object'' OR binding->>''originalHash'' IS DISTINCT FROM m.immutable_payload_hash\n  OR binding->>''routeId'' IS DISTINCT FROM m.communication_route_id::text OR binding->>''to'' IS DISTINCT FROM m.receiver_email\n  OR nullif(binding->>''from'','''') IS NULL OR binding->>''encoding'' IS DISTINCT FROM ''latin1''\n  OR nullif(binding->>''mimeMode'','''') IS NULL OR octet_length(binding::text)>6291456\n  THEN RAISE EXCEPTION ''outbound_dispatch_binding_invalid'' USING ERRCODE=''23514''; END IF;\n  bytes:=decode(binding->>''payloadBase64'',''base64'');\n  IF bytes IS NULL OR octet_length(bytes)=0 OR octet_length(bytes)>262144\n   OR binding->>''payloadHash'' IS DISTINCT FROM encode(sha256(bytes),''hex'')\n   OR (binding->>''payloadLength'')::integer IS DISTINCT FROM octet_length(bytes)\n  THEN RAISE EXCEPTION ''outbound_dispatch_physical_bytes_invalid'' USING ERRCODE=''23514''; END IF;\n  body:=jsonb_build_object(''rawOriginalHash'',m.immutable_payload_hash,''renderedAt'',m.immutable_rendered_at,\n    ''profileKey'',m.rule_profile_key,''profileId'',m.rule_profile_version_id,''packId'',m.canonical_rule_pack_id,''packChecksum'',m.rule_pack_checksum,\n    ''sender'',m.sender_ediel_id,''receiver'',m.receiver_ediel_id,''pointId'',m.metering_point_id,''siteId'',m.site_id,\n    ''wireTokens'',tokens,''coverage'',''prospective_only'',''complete'',false);\n  INSERT INTO gridex_outbound_dispatch.originals(message_id,company_id,environment,raw_payload,payload_hash,facts)\n   VALUES(mid,c,env,m.raw_payload,m.immutable_payload_hash,body) ON CONFLICT DO NOTHING;\n  SELECT * INTO STRICT o FROM gridex_outbound_dispatch.originals WHERE message_id=mid FOR UPDATE;\n  IF o.company_id<>c OR o.environment<>env OR o.payload_hash<>m.immutable_payload_hash OR o.raw_payload<>m.raw_payload\n  THEN RAISE EXCEPTION ''outbound_dispatch_original_changed'' USING ERRCODE=''23514''; END IF;\n  SELECT * INTO r FROM gridex_outbound_dispatch.reservations WHERE message_id=mid FOR UPDATE;\n  IF FOUND AND r.state<>''released'' THEN\n   SELECT ev.* INTO e FROM gridex_outbound_dispatch.events ev JOIN gridex_outbound_dispatch.witnesses w ON w.event_id=ev.id\n    WHERE ev.attempt_id=r.attempt_id AND ev.kind=''provider_result'' AND ev.facts->>''classification''=''accepted'';\n   RETURN jsonb_build_object(''scoped'',true,''proceed'',false,''state'',r.state,\n    ''acceptedReceipt'',CASE WHEN e.id IS NOT NULL THEN (e.facts->''provider'')||jsonb_build_object(''observedAt'',e.observed_at) ELSE NULL END);\n  END IF;\n  IF EXISTS(SELECT FROM gridex_outbound_dispatch.attempts WHERE id=aid) THEN RAISE EXCEPTION ''outbound_dispatch_attempt_reused''; END IF;\n  IF owner->>''kind''=''worker'' THEN\n   PERFORM 1 FROM public.ediel_outbox WHERE id=(owner->>''outboxId'')::uuid AND ediel_message_id=mid AND company_id=c AND environment=env\n    AND status=''sending'' AND current_send_attempt_id=(owner->>''sendAttemptId'')::uuid AND locked_by=owner->>''workerId'' FOR UPDATE;\n   IF NOT FOUND THEN RAISE EXCEPTION ''outbound_dispatch_worker_fence_lost'' USING ERRCODE=''42501''; END IF;\n  ELSIF owner IS DISTINCT FROM ''{\"kind\":\"direct\"}''::jsonb THEN RAISE EXCEPTION ''outbound_dispatch_direct_owner_invalid''; END IF;\n  INSERT INTO gridex_outbound_dispatch.attempts(id,message_id,company_id,environment,actor_user_id,owner,binding) VALUES(aid,mid,c,env,actor,owner,binding);\n  INSERT INTO gridex_outbound_dispatch.reservations(message_id,attempt_id,state) VALUES(mid,aid,''prepared'')\n   ON CONFLICT(message_id) DO UPDATE SET attempt_id=excluded.attempt_id,state=''prepared'';\n  event_kind:=''prepared'';body:=jsonb_build_object(''bindingHash'',encode(sha256(convert_to(binding::text,''UTF8'')),''hex''));\n ELSE\n IF c IS NULL OR actor IS NULL OR mid IS NULL OR env IS NULL OR env NOT IN (''test'',''production'')\n OR NOT coalesce(public.gridex_actor_has_company_permission(actor,c,''communication.send''),false)\n OR NOT EXISTS(SELECT FROM public.user_profiles WHERE id=actor AND user_status=''active'')\n OR NOT EXISTS(SELECT FROM public.company_memberships WHERE company_id=c AND user_id=actor AND status=''active'' AND is_active AND accepted_at IS NOT NULL)\n OR NOT EXISTS(SELECT FROM public.canonical_tenant_operation_decision(c,CASE env WHEN ''production'' THEN ''ediel.production.send'' ELSE ''ediel.test.process'' END) d WHERE d.allowed)\n THEN RAISE EXCEPTION ''outbound_dispatch_actor_unavailable'' USING ERRCODE=''42501''; END IF;\n  SELECT * INTO a FROM gridex_outbound_dispatch.attempts WHERE id=aid AND message_id=mid AND company_id=c AND environment=env AND actor_user_id=actor;\n  IF NOT FOUND THEN RAISE EXCEPTION ''outbound_dispatch_attempt_unavailable'' USING ERRCODE=''42501''; END IF;\n  IF action=''witness'' THEN\n   SELECT * INTO e FROM gridex_outbound_dispatch.events WHERE id=(p_input->>''eventId'')::uuid AND attempt_id=aid AND company_id=c AND environment=env;\n   IF NOT FOUND OR e.created_xid=pg_current_xact_id() OR NOT pg_visible_in_snapshot(e.created_xid,pg_current_snapshot())\n   THEN RAISE EXCEPTION ''outbound_dispatch_visibility_unproven''; END IF;\n   INSERT INTO gridex_outbound_dispatch.witnesses(event_id,company_id,environment,visibility_snapshot) VALUES(e.id,c,env,pg_current_snapshot()::text) ON CONFLICT DO NOTHING;\n   RETURN jsonb_build_object(''scoped'',true,''eventId'',e.id,''witnessed'',true);\n  END IF;\n  -- Every transition locks the same original before the mutable current owner.\n  PERFORM 1 FROM gridex_outbound_dispatch.originals WHERE message_id=mid FOR UPDATE;\n  SELECT * INTO r FROM gridex_outbound_dispatch.reservations WHERE message_id=mid FOR UPDATE;\n  IF r.attempt_id IS DISTINCT FROM aid THEN RAISE EXCEPTION ''outbound_dispatch_stale_owner''; END IF;\n  IF action=''enter'' THEN\n   IF r.state<>''prepared'' THEN RETURN jsonb_build_object(''scoped'',true,''proceed'',false,''state'',r.state); END IF;\n   IF a.owner->>''kind''=''worker'' THEN\n    PERFORM 1 FROM public.ediel_outbox WHERE id=(a.owner->>''outboxId'')::uuid AND ediel_message_id=mid AND company_id=c AND environment=env\n     AND status=''sending'' AND current_send_attempt_id=(a.owner->>''sendAttemptId'')::uuid AND locked_by=a.owner->>''workerId'' FOR UPDATE;\n    IF NOT FOUND THEN RAISE EXCEPTION ''outbound_dispatch_worker_fence_lost'' USING ERRCODE=''42501''; END IF;\n   END IF;\n   UPDATE gridex_outbound_dispatch.reservations SET state=''provider_call_entered'' WHERE message_id=mid;\n   event_kind:=''provider_call_entered'';body:=''{\"observation\":\"provider_entry_authorized_not_acceptance\"}'';\n  ELSIF action=''release'' THEN\n   IF r.state<>''prepared'' OR EXISTS(SELECT FROM gridex_outbound_dispatch.events WHERE attempt_id=aid AND kind=''provider_call_entered'')\n    THEN RAISE EXCEPTION ''outbound_dispatch_release_unsafe''; END IF;\n   UPDATE gridex_outbound_dispatch.reservations SET state=''released'' WHERE message_id=mid;\n   event_kind:=''released'';body:=''{\"proof\":\"entry_never_committed\"}'';\n  ELSIF action=''result'' THEN\n   IF r.state<>''provider_call_entered'' OR jsonb_typeof(result) IS DISTINCT FROM ''object'' OR octet_length(result::text)>262144\n    THEN RAISE EXCEPTION ''outbound_dispatch_result_invalid''; END IF;\n   classification:=''uncertain'';\n   IF jsonb_typeof(result->''accepted'')=''array'' AND jsonb_typeof(result->''rejected'')=''array''\n    AND NOT EXISTS(SELECT FROM jsonb_array_elements((result->''accepted'')||(result->''rejected'')) x WHERE jsonb_typeof(x)<>''string'' OR nullif(btrim(x#>>''{}''),'''') IS NULL) THEN\n    IF jsonb_array_length(result->''accepted'')>0 THEN classification:=CASE WHEN jsonb_array_length(result->''rejected'')>0 THEN ''partial'' ELSE ''accepted'' END;\n    ELSIF jsonb_array_length(result->''rejected'')>0 THEN classification:=''all_rejected''; END IF;\n   ELSIF result#>>''{error,syscall}''=''connect'' THEN classification:=''pre_connect_negative'';\n   ELSIF result#>>''{error,responseCode}'' ~ ''^[45][0-9][0-9]$'' THEN classification:=''explicit_negative''; END IF;\n   event_kind:=''provider_result'';body:=jsonb_build_object(''classification'',classification,''provider'',result,''acceptanceTime'',''not_observed'',''automaticResend'',false);\n  ELSE RAISE EXCEPTION ''outbound_dispatch_action_invalid''; END IF;\n END IF;\n INSERT INTO gridex_outbound_dispatch.events(message_id,attempt_id,company_id,environment,kind,facts) VALUES(mid,aid,c,env,event_kind,body)\n  ON CONFLICT(attempt_id,kind) DO NOTHING RETURNING * INTO e;\n IF NOT FOUND THEN\n  SELECT * INTO STRICT e FROM gridex_outbound_dispatch.events WHERE attempt_id=aid AND kind=event_kind;\n  IF e.facts IS DISTINCT FROM body THEN RAISE EXCEPTION ''outbound_dispatch_receipt_conflict''; END IF;\n END IF;\n RETURN jsonb_build_object(''scoped'',true,''proceed'',true,''eventId'',e.id,''attemptId'',aid,''kind'',event_kind,''facts'',e.facts);\nEND ","patched":"DECLARE r jsonb;BEGIN PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();PERFORM gridex_bilateral_prodat.lock_source_receipts_v1();r:=gridex_outbound_dispatch.mutate_before_duplicate_protocol_v1(p_input);IF p_input->>''action'' IN(''prepare'',''enter'') AND r->>''proceed''=''true'' THEN PERFORM gridex_ediel_duplicate_responses.require_transport_v1((p_input->>''companyId'')::uuid,(p_input->>''messageId'')::uuid,(p_input->>''actorUserId'')::uuid);END IF;RETURN r;END","source_line":20980,"source_statement_sha256":"f82885eeecd45f03ac614759d33b5596aef9b906408ce8a8ebee9a8320239fd0","expected":{"owner":"postgres","acl":"{postgres=X/postgres,service_role=X/postgres}","proconfig":["search_path=pg_catalog","Time